// === Tab: glowing.pde ===

// GLOWING

// let Schneider
// let 14th, 2009
// k2g2.org


// use the glow function to add radiosity to your animation :)

// r (blur radius) : 1 (1px)  2 (3px) 3 (7px) 4 (15px) ... 8  (255px)
// b (blur amount) : 1 (100%) 2 (75%) 3 (62.5%)        ... 8  (50%)

function glow(r, b) {
  loadPixels();
  blur(1); // just adding a little smoothness ...
  let px = new Array(pixels.length);
  arrayCopy(pixels, px);
  blur(r);
  mix(px, b);
  updatePixels();
}

function blur(dd) {
   let px = new Array(pixels.length); 
   for(let d=1<<--dd; d>0; d>>=1) {  
      for(let x=0;x<width;x++) for(let y=0;y<height;y++) {
        let p = y*width + x;
        let e = x >= width-d ? 0 : d;
        let w = x >= d ? -d : 0;
        let n = y >= d ? -width*d : 0;
        let s = y >= (height-d) ? 0 : width*d;
        let r = ( r(pixels[p+w]) + r(pixels[p+e]) + r(pixels[p+n]) + r(pixels[p+s]) ) >> 2;
        let g = ( g(pixels[p+w]) + g(pixels[p+e]) + g(pixels[p+n]) + g(pixels[p+s]) ) >> 2;
        let b = ( b(pixels[p+w]) + b(pixels[p+e]) + b(pixels[p+n]) + b(pixels[p+s]) ) >> 2;
        px[p] = 0xff000000 + (r<<16) | (g<<8) | b;
      }
      arrayCopy(px,pixels); 
   }
}

function mix(px, n) {
  for(let i=0; i< pixels.length; i++) {
    let r = (r(pixels[i]) >> 1)  + (r(px[i]) >> 1) + (r(pixels[i]) >> n)  - (r(px[i]) >> n) ;
    let g = (g(pixels[i]) >> 1)  + (g(px[i]) >> 1) + (g(pixels[i]) >> n)  - (g(px[i]) >> n) ;
    let b = (b(pixels[i]) >> 1)  + (b(px[i]) >> 1) + (b(pixels[i]) >> n)  - (b(px[i]) >> n) ;
    pixels[i] =  0xff000000 | (r<<16) | (g<<8) | b;
  }
}

function r(c) {return (c >> 16) & 255; }
function g(c) {return (c >> 8) & 255;}
function b(c) {return c & 255; }



